            <svg data-map-mode-icon="night" viewBox="0 0 24 24" fill="none"><path d="M19.6 15.1A8 8 0 0 1 8.9 4.4 8.1 8.1 0 1 0 19.6 15.1Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg>
